INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Modularisierung nur für große Projekte sinnvoll?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren von Struktur"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Prinzip der Modularisierung?', 3, '[{"text": "Code in unabhängige Teile aufteilen", "correct": true, "because": "Fördert Wartbarkeit"}, {"text": "Datenfluss optimieren", "correct": false, "because": "Nicht primär"}, {"text": "UI gestalten", "correct": false, "because": "Kein Designfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Modularisierung?', 5, '[{"text": "Module", "correct": true, "because": "Unabhängige Einheiten"}, {"text": "Schnittstellen", "correct": true, "because": "Kommunikation definieren"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Hardwareknoten", "correct": false, "because": "Kein Code-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Modularisierung erhöht Wiederverwendbarkeit. b) Sie macht Code immer komplexer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Komplexität kann sinken"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Modularisierung?', 4, '[{"text": "Modulgrenze", "correct": false, "because": "Definiert Unabhängigkeit"}, {"text": "Schnittstellen", "correct": false, "because": "Ermöglichen Kommunikation"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Modularisierungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Modularisierung auch ohne Schnittstellen funktioniert?', 2, '[{"text": "Nein", "correct": true, "because": "Schnittstellen sind essenziell"}, {"text": "Ja", "correct": false, "because": "Kommunikation nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Schnittstellen bei der Modularisierung?', 3, '[{"text": "Kommunikation ermöglichen", "correct": true, "because": "Verbinden Module"}, {"text": "Daten speichern", "correct": false, "because": "Nicht primär"}, {"text": "UI rendern", "correct": false, "because": "Kein UI-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien unterstützen Modularisierung?', 5, '[{"text": "Kapselung", "correct": true, "because": "Verbirgt Details"}, {"text": "Lose Kopplung", "correct": true, "because": "Reduziert Abhängigkeiten"}, {"text": "Datenfluss", "correct": false, "because": "Kein Prinzip"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Modularisierung verbessert Wartbarkeit. b) Sie macht Code immer langsamer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Leistung nicht zwangsläufig betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Modularisierung?', 4, '[{"text": "Modulaufteilung", "correct": false, "because": "Kern der Struktur"}, {"text": "Schnittstellen", "correct": false, "because": "Ermöglichen Interaktion"}, {"text": "3D-Grafiken", "correct": true, "because": "Kein Modularisierungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Modularisierung nur für Software?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Systeme oder Prozesse"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien fördern Modularisierung?', 4, '[{"text": "Hohe Kohäsion", "correct": true, "because": "Module fokussiert"}, {"text": "Lose Kopplung", "correct": true, "because": "Abhängigkeiten minimieren"}, {"text": "Datenfluss", "correct": false, "because": "Kein Prinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Modularisierung die Entwicklung verzögert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Langfristig Zeit sparend"}, {"text": "Ja", "correct": false, "because": "Initialaufwand kompensierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Modularisierung?', 3, '[{"text": "Unabhängigkeit der Module", "correct": true, "because": "Fördert Flexibilität"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "UI-Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Modularisierung reduziert Abhängigkeiten. b) Sie ist nur für große Teams.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch kleine Teams profitieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Modularisierung?', 5, '[{"text": "Wiederverwendbarkeit", "correct": true, "because": "Module wiederverwendbar"}, {"text": "Testbarkeit", "correct": true, "because": "Module einzeln testbar"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}, {"text": "UI-Animation", "correct": false, "because": "Kein UI-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Modularisierung unwichtig?', 3, '[{"text": "Schnittstellendefinition", "correct": false, "because": "Kommunikation ermöglichen"}, {"text": "Modulgröße", "correct": false, "because": "Beeinflusst Übersicht"}, {"text": "Blinkende Anzeige", "correct": true, "because": "Kein Modularisierungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Modularisierung die Komplexität erhöhen?', 3, '[{"text": "Nein", "correct": true, "because": "Reduziert Komplexität meist"}, {"text": "Ja", "correct": false, "because": "Nur bei schlechter Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Modularisierung für Tests hilft?', 2, '[{"text": "Ja", "correct": true, "because": "Module einzeln testbar"}, {"text": "Nein", "correct": false, "because": "Testbarkeit verbessert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip wähle ich für die Modularisierung?', 4, '[{"text": "Kapselung", "correct": true, "because": "Details verbergen"}, {"text": "Datenfluss", "correct": false, "because": "Kein Prinzip"}, {"text": "UI-Steuerung", "correct": false, "because": "Kein Modularisierungsaspekt"}]');
